"""Cuaderno del estudiante, 6.º básico Lenguaje y Comunicación, OA 05 (análisis de poemas).

Todos los poemas son originales y breves (los poemas reales quedan para el docente); en cada ejercicio
las barras / separan los versos y el poema necesario está escrito en el enunciado.
"""
from __future__ import annotations

from student_content_le6_a import E, L, MAT, cnt, n_words
from student_lessons import arith

OA5 = "LE06 OA 05"

SENT = "Huele a pan en la esquina, / suena el tranvía a lo lejos, / la mano en el pasamanos / siente el frío del hierro."
TRIS = "La tarde se pone gris / y el patio se queda solo; / la silla vacía espera / y yo, sin ganas de nada."
ALEG = "Salta el sol sobre los techos, / la calle huele a manzana, / y yo, con las manos al viento, / quiero abrazar la mañana."
PERS = "El mar se quitó el sombrero, / la luna le dio la mano / y el viento, medio dormido, / bostezó sobre la playa."
COMP = "Tu risa es como una campana, / tus ojos, cual dos lagunas, / y tus manos, tan tibias / como el pan recién horneado."
HIPER = "Te esperé mil años en la esquina, / lloré un océano de tristeza / y de tanto bostezar / casi me trago la plaza."
SON = "El río rueda y rumorea / entre rocas rojas y arena; / plic, plic, plic, gotea la lluvia / sobre la hoja de la higuera."
SON2 = "Susurra el sauce al sol, / suave, sobre el sendero; / tic-tac, tic-tac, el reloj / cuenta los segundos lentos."
FIN = "La lluvia toca la puerta / con sus dedos de agua fina. / Pum, pum, tamborilea el techo / y llovió un mar entero en mi patio. / Yo, quieto como un gato, / escucho junto a la ventana."


def versos(poema):
    return str(poema.count("/") + 1)


L(OA5, 1,
  MAT,
  "Aprenderé a reconocer cómo el lenguaje poético apela a los sentidos, sugiere estados de ánimo y crea imágenes en quien lee, y para qué analizar un poema.",
  ["Sé qué es un verso.", "Conozco los cinco sentidos."],
  ["Un poema usa el lenguaje de un modo especial: busca que el lector sienta y se imagine cosas, no solo que entienda datos. Por eso se llama lenguaje poético. El poeta elige palabras que apelan a los sentidos: la vista, el oído, el olfato, el gusto y el tacto. Así podemos ver, oír, oler o sentir lo que el poema describe.",
   "El lenguaje poético también sugiere estados de ánimo. Un poema puede transmitir alegría, tristeza, calma o nostalgia aunque no diga «estoy triste». Las palabras como «gris», «solo» o «vacía» sugieren tristeza; «salta», «sol», «abrazar» sugieren alegría. Esas palabras ayudan a crear imágenes, que son representaciones que el lector se forma en la mente.",
   "Analizar un poema es preguntarse: ¿qué sentidos apela?, ¿qué estado de ánimo transmite?, ¿qué imágenes me hago? y ¿qué palabras lo provocan? Responder con ejemplos del poema hace que tu análisis tenga evidencia. Ese es el desafío de esta clase."],
  [("verso", "cada línea de un poema"), ("imagen", "representación que el lector se forma en la mente"), ("estado de ánimo", "emoción que transmite un poema, como alegría o tristeza"), ("lenguaje poético", "uso especial de las palabras para hacer sentir e imaginar")],
  [("Hallar los sentidos", f"Lee el poema: «{SENT}» ¿A qué sentidos apela el primer verso?",
    ["Leo el primer verso: «Huele a pan en la esquina».", "El verbo «huele» se relaciona con el olfato.", "Apela al olfato."],
    "Al olfato"),
   ("Hallar el estado de ánimo", f"Lee: «{TRIS}» ¿Qué estado de ánimo transmite?",
    ["Busco palabras: «gris», «solo», «vacía», «sin ganas».", "Todas sugieren soledad y desánimo.", "Concluyo: tristeza."],
    "Tristeza")],
  [("Decir que un poema trata solo de lo que dice la primera línea.", "No se considera el poema completo.", "Lee todo y piensa qué sensación deja."),
   ("Afirmar un estado de ánimo sin citar palabras.", "No se usa evidencia.", "Cita las palabras que lo sugieren.")],
  ([E(f"Lee: «{SENT}» ¿Cuántos versos tiene este poema? (Las barras los separan.)", versos(SENT), "Se cuentan los versos separados por barras."),
    E("¿Con qué sentido se relaciona el verbo «huele»: el olfato o la vista?", "El olfato", "Huele se relaciona con los olores."),
    E("¿Qué es un verso: cada línea de un poema o un párrafo?", "Cada línea de un poema", "El poema se organiza en versos.")],
   [E(f"Con este poema: «{SENT}» ¿a qué sentido apela «suena el tranvía a lo lejos»?", "Al oído", "Se oye un sonido."),
    E(f"Con este poema: «{SENT}» ¿a qué sentido apela «siente el frío del hierro»?", "Al tacto", "El frío se percibe al tocar."),
    E(f"Lee: «{ALEG}» ¿Qué estado de ánimo transmite: alegría o tristeza?", "Alegría", "Palabras como «salta», «sol» y «abrazar» sugieren alegría.")],
   [E(f"En «{SENT}» ¿cuántos sentidos distintos se mencionan en los versos 1, 2 y 4?", "3", "Olfato, oído y tacto."),
    E(f"Lee: «{TRIS}» ¿Qué palabra sugiere soledad: «gris» o «solo»? Elige la más directa.", "solo", "Nombra directamente la falta de compañía."),
    arith("Un poema tiene 4 estrofas de 4 versos. ¿Cuántos versos tiene?", "4*4", "Se multiplica el número de estrofas por los versos de cada una.")],
   [E(f"Lee: «{ALEG}» y «{TRIS}». ¿En cuál se dice «la calle huele a manzana»?", "En el poema alegre", "Está en el poema que empieza «Salta el sol sobre los techos»."),
    E("Un lector dice que el poema de la tarde gris es alegre. ¿Qué palabras muestran que no es así: «gris», «solo» y «vacía» o «sol» y «manzana»?", "«gris», «solo» y «vacía»", "Sugieren tristeza y soledad.")],
   [E(f"Lee: «{ALEG}» Escribe cuántas palabras tiene el verso «la calle huele a manzana».", n_words("la calle huele a manzana"), "Se cuentan las palabras separadas por espacios."),
    E("Un poema dice «huele a lluvia, suena un trueno, se ve un cielo oscuro». ¿Cuántos sentidos distintos apela?", "3", "Olfato, oído y vista.")]),
  [E("Quieres escribir un poema sobre la hora de comer en casa. Para apelar al olfato, ¿qué verso eliges: «huele a sopa humeante» o «tiene una mesa»?", "«Huele a sopa humeante»", "Menciona un olor concreto.")],
  [E("¿Qué sentido relacionas con una palabra como «suena»?", "El oído", "Suena se percibe con los oídos."),
   E("¿Un poema puede sugerir un estado de ánimo sin decir «estoy triste»?", "Sí", "Lo sugiere con las palabras elegidas."),
   E("¿Qué es una imagen en un poema?", "Una representación que el lector se forma en la mente", "Se produce al imaginar lo leído.")],
  ("Lee: «El patio huele a tierra mojada, / la ventana brilla de gotas, / el gato duerme tibio / y un trueno rueda lejos.» 1) ¿A qué sentidos apela? 2) ¿Qué estado de ánimo transmite? 3) Escribe la imagen que te formas.",
   "1) Olfato (huele a tierra mojada), vista (la ventana brilla de gotas), tacto (tibio) y oído (trueno rueda). 2) Calma. 3) Veo un patio mojado con una ventana gris y un gato tibio dormido, mientras suena un trueno lejano.",
   ["identifica sentidos con evidencia", "relaciona palabras con el estado de ánimo", "describe una imagen coherente"], ["tres respuestas escritas"], ["decir un estado de ánimo sin evidencia", "no citar versos"], "Subraya las palabras del poema que usaste como evidencia."),
  "Lee en voz alta un poema que te guste y di a qué sentidos apela.",
  "Escribe cuatro versos que apelen a tres sentidos distintos.")

L(OA5, 2,
  MAT,
  "Aprenderé a modelar cómo se lee un poema pensando en voz alta: qué imagen se forma, qué sentido apela y qué estado de ánimo sugiere.",
  ["Reconozco sentidos y estados de ánimo.", "Cito versos."],
  ["Un lector experto lee un poema despacio y piensa en voz alta. Dice cosas como: «En este verso veo…», «Esta palabra me hace sentir…», «Por estas palabras creo que el ambiente es de calma». Esa conversación interior es lo que se modela, para que otros aprendan cómo hacerlo.",
   "El orden sugerido es: primero leer el poema completo, luego releer por partes; subrayar palabras que apelen a los sentidos; imaginar la escena como una pequeña película; nombrar el estado de ánimo; y, por último, explicar con tus palabras qué quiso transmitir el poeta. Cada afirmación debe tener un verso que la respalde.",
   "No hay una sola imagen posible: cada lector se forma la suya. Pero toda imagen tiene que ser coherente con lo que el poema dice. Si un poema habla de un patio mojado y de un trueno, no sería coherente imaginar un desierto soleado."],
  [("modelar", "mostrar en voz alta cómo se hace algo"), ("subrayar", "marcar con una línea palabras importantes"), ("coherente", "que no se contradice con lo que dice el texto"), ("escena", "situación que se imagina como si se viera")],
  [("Pensar en voz alta", f"Lee: «{SENT}» Piensa en voz alta el verso «suena el tranvía a lo lejos».",
    ["Veo la palabra «suena»: apela al oído.", "«A lo lejos» me hace imaginar un ruido que se acerca despacio.", "Siento una ciudad tranquila a lo lejos."],
    "Apela al oído y sugiere una ciudad tranquila"),
   ("Imagen coherente", f"Lee: «{PERS}» ¿Qué imagen coherente puedes formar?",
    ["Hay un mar, una luna, el viento y una playa.", "Es de noche porque aparece la luna.", "Imagino una noche tranquila en la playa."],
    "Una noche tranquila en la playa")],
  [("Imaginar algo que el poema no dice.", "Se agrega información ajena.", "Mantén tu imagen coherente con los versos."),
   ("Leer sin detenerse a pensar.", "Se lee igual que un texto informativo.", "Lee despacio y subraya.")],
  ([E(f"Lee: «{PERS}» ¿Cuántos versos tiene?", versos(PERS), "Se cuentan separados por barras."),
    E("El primer paso para analizar un poema, ¿es leerlo completo o saltar a la última línea?", "Leerlo completo", "Hay que conocer todo el poema."),
    E(f"En el poema «{PERS}», ¿qué astro aparece: el sol o la luna?", "La luna", "El segundo verso la nombra.")],
   [E(f"Con el poema «{PERS}» ¿es coherente imaginar un desierto a pleno sol?", "No", "El poema habla de mar y de luna."),
    E(f"En «{ALEG}» ¿a qué sentido apela «la calle huele a manzana»?", "Al olfato", "El verbo oler lo indica."),
    E("¿Por qué conviene subrayar palabras que apelan a los sentidos: para encontrar evidencia o para borrar versos?", "Para encontrar evidencia", "Esas palabras respaldan tu análisis.")],
   [E(f"En «{PERS}» ¿qué palabra del tercer verso sugiere tranquilidad: «medio dormido» o «el viento»?", "«medio dormido»", "Sugiere calma y quietud."),
    arith("Un poema tiene 6 versos. Subrayas 2 palabras por verso. ¿Cuántas palabras subrayas?", "6*2", "Se multiplica por los versos."),
    E(f"En «{TRIS}», ¿qué verso muestra la soledad con un objeto: «la silla vacía espera» o «la tarde se pone gris»?", "«La silla vacía espera»", "Una silla vacía sugiere ausencia.")],
   [E(f"Dos lectores leen «{ALEG}». Uno imagina una mañana lluviosa y triste. Otro, una mañana luminosa. ¿Cuál imagen es coherente?", "La mañana luminosa", "El poema habla de sol y alegría."),
    E("Un lector dice: «Este poema me da calma, por eso ‘medio dormido’ es la palabra clave». ¿Su afirmación tiene verso que la respalde?", "Sí", "Cita una expresión del poema.")],
   [E(f"En «{PERS}» ¿cuál es una escena posible: la playa en la noche con una luna que da la mano al mar o una ciudad ruidosa al mediodía?", "La playa en la noche con una luna que da la mano al mar", "Combina elementos del poema."),
    E("Al modelar tu lectura dices «veo… siento… creo». ¿Qué muestras con eso: tu forma de pensar o tu letra?", "Tu forma de pensar", "Haces visible el pensamiento.")]),
  [E("Un compañero lee un poema y dice solo «está lindo». ¿Qué le falta para modelar el análisis: señalar un verso y decir qué siente o repetir «lindo»?", "Señalar un verso y decir qué siente", "Así tiene evidencia.")],
  [E("¿Se debe leer un poema una sola vez rápido o despacio y más de una vez?", "Despacio y más de una vez", "Así se descubren más detalles."),
   E("¿Una imagen coherente respeta lo que dice el poema?", "Sí", "No lo contradice."),
   E("¿Para qué subrayas palabras clave?", "Para tener evidencia de tu análisis", "Respaldan lo que afirmas.")],
  ("Lee: «Se apaga la tarde en el río, / los patos regresan callados, / un grillo ensaya su canto / y todo huele a pasto mojado.» Piensa en voz alta: 1) dos palabras que apelen a los sentidos y a cuáles, 2) el estado de ánimo, 3) la imagen que te formas.",
   "1) «callados» (oído) y «huele» (olfato). 2) Calma. 3) Imagino un río al atardecer, con patos que vuelven en silencio, un grillo que canta y olor a pasto mojado.",
   ["relaciona palabras con sentidos", "nombra un estado de ánimo con base en el poema", "imagen coherente"], ["tres respuestas escritas"], ["imagen que contradice el poema", "no citar palabras"], "Lee en voz alta tus pensamientos como si se lo mostraras a un compañero."),
  "Elige un poema corto y piensa en voz alta sobre dos versos mientras alguien te escucha.",
  "Escribe cinco frases que sirvan para comenzar un análisis, como «En este verso veo…».")

L(OA5, 3,
  MAT,
  "Aprenderé a identificar personificaciones, comparaciones e hipérboles en un poema, a citar la evidencia y a explicar su significado dentro del poema.",
  ["Distingo sentidos y estados de ánimo.", "Sé que el lenguaje poético usa figuras."],
  ["Las figuras literarias son recursos que embellecen el lenguaje y dicen más con menos. Tres de ellas son la personificación, la comparación y la hipérbole. La personificación atribuye acciones o cualidades humanas a cosas, animales o fenómenos: «el mar se quitó el sombrero».",
   "La comparación une dos cosas por su parecido, usando palabras como «como», «cual» o «parece»: «tu risa es como una campana». La hipérbole exagera mucho para destacar una idea o un sentimiento: «lloré un océano de tristeza». En los tres casos, no se debe leer literalmente: el poeta busca un efecto.",
   "Para analizar una figura, sigue tres pasos: 1) cita el verso; 2) di cuál figura es y por qué; 3) explica qué significa dentro del poema. Por ejemplo: «‘El viento bostezó’ es una personificación porque el viento hace algo humano; significa que el viento sopla suave y adormecido»."],
  [("personificación", "atribuir acciones o cualidades humanas a cosas o animales"), ("comparación", "unir dos cosas por su parecido con «como», «cual» o «parece»"), ("hipérbole", "exageración que destaca una idea o emoción"), ("figura literaria", "recurso que embellece o refuerza el lenguaje")],
  [("Identificar una personificación", f"Lee: «{PERS}» ¿Qué verso es una personificación?",
    ["Busco acciones humanas en cosas.", "«El mar se quitó el sombrero»: el mar hace algo humano.", "Es una personificación."],
    "«El mar se quitó el sombrero»"),
   ("Identificar una hipérbole", f"Lee: «{HIPER}» ¿Qué verso es una hipérbole y qué significa?",
    ["«Te esperé mil años» exagera la espera.", "Nadie espera mil años.", "Significa que esperó muchísimo."],
    "«Te esperé mil años»: esperó muchísimo")],
  [("Llamar comparación a cualquier verso con «como» sin pensar.", "Se aplica la regla sin revisar.", "Comprueba que se unan dos cosas por su parecido."),
   ("Leer la hipérbole de forma literal.", "No se advierte la exageración.", "Pregunta: ¿puede ocurrir realmente?")],
  ([E(f"Lee: «{COMP}» ¿Qué palabra señala la comparación en el primer verso?", "como", "«Como una campana» une dos cosas."),
    E("«El viento bostezó»: ¿es una personificación o una hipérbole?", "Una personificación", "El viento hace algo humano: bostezar."),
    E("«Lloré un océano de tristeza»: ¿es una hipérbole o una comparación?", "Una hipérbole", "Exagera la cantidad de llanto.")],
   [E(f"Lee: «{COMP}» ¿Qué dos cosas se comparan en «tu risa es como una campana»?", "La risa y una campana", "Se unen por el parecido del sonido."),
    E(f"Lee: «{HIPER}» ¿qué verso exagera el cansancio al bostezar: el tercero o el cuarto? Elige el verso que muestra la exageración.", "El cuarto", "«Casi me trago la plaza» exagera."),
    E("«La luna le dio la mano al mar»: ¿es una personificación o una comparación?", "Una personificación", "La luna hace algo humano.")],
   [E(f"En «{COMP}» ¿cuántas comparaciones hay si cada verso con «como», «cual» o «tan… como» cuenta como una?", "3", "Hay «como una campana», «cual dos lagunas» y «tan tibias como el pan»."),
    arith("En un poema hay 2 personificaciones, 3 comparaciones y 1 hipérbole. ¿Cuántas figuras hay en total?", "2+3+1", "Se suman todas las figuras."),
    E(f"Lee: «{PERS}» ¿Cuántos elementos de la naturaleza hacen cosas humanas en este poema?", "3", "El mar se quita el sombrero, la luna da la mano y el viento bosteza.")],
   [E("Un lector dice que «tengo un hambre que me comería el mundo» es una comparación. ¿Es correcto?", "No", "Es una hipérbole porque exagera, no compara con «como»."),
    E("«Tus ojos, cual dos lagunas»: ¿qué indica que es una comparación: la palabra «cual» o la palabra «ojos»?", "La palabra «cual»", "Une dos cosas por su parecido.")],
   [E(f"Dos lectoras explican el verso «bostezó sobre la playa», que habla del viento. Ana: «El viento se durmió de verdad». Beto: «El viento sopló suave y adormecido». ¿Quién interpreta mejor la personificación?", "Beto", "No toma literalmente la acción humana."),
    E("Un verso dice «me cayó un cielo encima de tanta alegría». ¿Es hipérbole o personificación?", "Hipérbole", "Exagera lo que se siente.")]),
  [E("En la sala, tu compañero dice «tengo mil cosas que hacer». ¿Qué figura usa si no son realmente mil: hipérbole o personificación?", "Hipérbole", "Exagera para destacar que tiene muchas tareas.")],
  [E("¿Qué figura exagera: la hipérbole o la comparación?", "La hipérbole", "Es una exageración."),
   E("¿Qué palabras señalan una comparación?", "Como, cual, parece", "Unen dos cosas por su parecido."),
   E("¿La personificación da cualidades humanas a cosas o animales?", "Sí", "Esa es su definición.")],
  ("Lee: «El sol se asomó bostezando, / sus rayos son como hilos de oro, / y yo, de tanta alegría, / podría volar hasta la luna.» Escribe una personificación, una comparación y una hipérbole del poema, con una frase de significado para cada una.",
   "Personificación: «El sol se asomó bostezando» (el sol amanece despacio). Comparación: «sus rayos son como hilos de oro» (los rayos brillan como oro). Hipérbole: «podría volar hasta la luna» (siente una alegría enorme).",
   ["cita cada verso", "nombra la figura con su razón", "explica el significado dentro del poema"], ["tres citas con explicación"], ["leer literal", "confundir figuras"], "Para cada figura, escribe el significado con la forma: «significa que…»."),
  "Inventa una frase con cada una de las tres figuras y pide a otra persona que las identifique.",
  "Busca en un poema cinco figuras y clasifícalas.")

L(OA5, 4,
  MAT,
  "Aprenderé a comparar cómo los efectos sonoros (aliteración y onomatopeya) refuerzan lo que dice un poema, y a decidir qué interpretación del efecto es la más adecuada.",
  ["Reconozco figuras como la personificación.", "Leo poemas en voz alta."],
  ["Los poemas se escuchan. La aliteración es la repetición de un mismo sonido en varias palabras cercanas, como «el río rueda y rumorea entre rocas rojas», donde se repite el sonido de la «r». La onomatopeya es una palabra que imita un sonido, como «plic, plic» para las gotas o «tic-tac» para un reloj.",
   "Los efectos sonoros refuerzan lo que dice el poema. La «r» repetida en «rueda y rumorea» suena como un río que corre. «Plic, plic, plic» hace oír la lluvia al leer. Para analizar un efecto, pregúntate: ¿qué sonido se repite?, ¿qué ruido imita?, ¿cómo refuerza lo que se dice o el estado de ánimo?",
   "Dos lectores pueden interpretar un efecto de modo distinto. Para decidir cuál interpretación es mejor, mira si se apoya en lo que dice el poema. Si la «s» repetida acompaña a un sauce que «susurra», la interpretación «suena como un susurro» se apoya en el texto; en cambio, «suena como un trueno» no lo hace."],
  [("aliteración", "repetición de un sonido en palabras cercanas"), ("onomatopeya", "palabra que imita un sonido"), ("efecto sonoro", "sonido del poema que refuerza lo que dice"), ("reforzar", "hacer más fuerte una idea o sensación")],
  [("Identificar una aliteración", f"Lee: «{SON}» ¿Qué sonido se repite en el primer y segundo verso?",
    ["Leo en voz alta: rueda, rumorea, rocas, rojas.", "Se repite el sonido de la «r».", "Es una aliteración que suena como un río que corre."],
    "El sonido de la «r», que refuerza el correr del río"),
   ("Identificar una onomatopeya", f"En el mismo poema, ¿qué palabra imita un sonido?",
    ["Busco palabras que parezcan ruido.", "«Plic, plic, plic» imita las gotas.", "Es una onomatopeya."],
    "«Plic, plic, plic»")],
  [("Llamar onomatopeya a cualquier palabra que suene fuerte.", "No imita un sonido real.", "Una onomatopeya imita un ruido."),
   ("Decir que la aliteración es repetir una palabra completa.", "Se confunde con la repetición.", "La aliteración repite un sonido.")],
  ([E(f"Lee: «{SON2}» ¿Qué palabra del tercer verso imita el sonido de un reloj?", "tic-tac", "Es una onomatopeya."),
    E("Una palabra que imita un sonido, ¿es una onomatopeya o una aliteración?", "Una onomatopeya", "Esa es su definición."),
    E("La repetición de un sonido en palabras cercanas, ¿es aliteración o personificación?", "Aliteración", "Esa es su definición.")],
   [E(f"En «{SON2}», ¿qué sonido se repite en «Susurra el sauce al sol»: la «s» o la «m»?", "La «s»", "Se repite en susurra, sauce y sol."),
    E("En «Susurra el sauce al sol, suave, sobre el sendero», ¿con qué se relaciona la «s» repetida: con un susurro suave o con un golpe fuerte?", "Con un susurro suave", "El sonido «s» recuerda un susurro."),
    E("«Plic, plic, plic» imita la caída de gotas. ¿Qué refuerza: la idea de lluvia o la de calor?", "La idea de lluvia", "Imita el sonido de las gotas.")],
   [E(f"En «{SON}» ¿cuántas veces aparece «plic» en el tercer verso?", "3", "Se repite tres veces."),
    arith("Un poema tiene 3 onomatopeyas por estrofa y 4 estrofas. ¿Cuántas onomatopeyas hay?", "3*4", "Se multiplica por las estrofas."),
    E(f"En «{SON2}», ¿cuántas veces se repite «tic-tac» en el tercer verso?", "2", "Aparece «tic-tac, tic-tac».")],
   [E("Dos lectores interpretan la «s» de «susurra el sauce al sol». Ana: «suena a susurro». Beto: «suena a explosión». ¿Cuál se apoya en el poema?", "Ana", "El verbo «susurra» respalda el sonido suave."),
    E("«Tic-tac, tic-tac, el reloj cuenta los segundos lentos». ¿Qué efecto refuerza la onomatopeya: el paso lento del tiempo o una carrera?", "El paso lento del tiempo", "El verso dice «segundos lentos».")],
   [E("Una lectora dice que en «el río rueda y rumorea entre rocas rojas» la repetición de la «r» imita el fluir del agua. Otro dice que no hay efecto. ¿Quién tiene un argumento con evidencia?", "La lectora", "Señala el sonido repetido y su relación con el río."),
    E("¿Pueden coexistir una aliteración y una onomatopeya en un mismo poema?", "Sí", "Los dos recursos pueden aparecer a la vez, como en los poemas de esta clase.")]),
  [E("Quieres que un cartel sobre la lluvia suene como la lluvia al leerlo en voz alta. ¿Qué recurso usas: onomatopeya como «plic, plic» o un número?", "Onomatopeya como «plic, plic»", "Imita el sonido de las gotas.")],
  [E("¿Qué es una aliteración?", "La repetición de un sonido en palabras cercanas", "Es un efecto sonoro."),
   E("¿Qué imita una onomatopeya?", "Un sonido", "Reproduce un ruido."),
   E("¿Para analizar un efecto debes decir cómo refuerza lo que dice el poema?", "Sí", "Ese es el objetivo.")],
  ("Lee en voz alta: «Rápido rueda el río, / raspa las rocas rojas; / crac, crac, crujen las ramas / sobre la roca roja.» 1) ¿Qué sonido se repite? 2) ¿Qué onomatopeya hay? 3) Explica cómo refuerzan lo que dice el poema.",
   "1) El sonido de la «r». 2) «Crac, crac». 3) La «r» repetida imita el agua que corre áspera sobre las rocas y «crac, crac» hace oír las ramas que crujen.",
   ["identifica la aliteración", "reconoce la onomatopeya", "explica el efecto con evidencia"], ["tres respuestas escritas"], ["decir que no hay efecto", "no relacionar el sonido con el contenido"], "Lee el poema en voz alta y marca con color los sonidos repetidos."),
  "Escribe dos versos con una aliteración y una onomatopeya y léelos en voz alta.",
  "Busca en un poema conocido una palabra que imite un sonido y explica qué refuerza.")

L(OA5, 5,
  MAT,
  "Aprenderé a producir mi propio comentario de un poema, explicando con ejemplos cómo el lenguaje poético, las figuras y los sonidos transmiten lo que dice.",
  ["Reconozco figuras y efectos sonoros.", "Cito versos."],
  ["Un comentario de poema es un texto breve en que explicas qué transmite el poema y cómo lo logra. Tiene tres partes: una oración inicial sobre el tema y el estado de ánimo; una o dos oraciones que explican, con versos como evidencia, las figuras o efectos sonoros; y una oración de cierre con tu impresión.",
   "Por ejemplo: «El poema transmite calma. Los versos ‘la luna le dio la mano’ y ‘el viento bostezó’ son personificaciones que muestran una noche tranquila. Al leerlo, imaginé una playa en silencio». Observa que se nombra el estado de ánimo, se citan versos, se identifican figuras y se explica qué significan.",
   "Evita decir solo «me gustó». Usa verbos como «transmite», «sugiere», «muestra», «refuerza» y conectores como «porque», «por eso», «además». Escribe con tus palabras, sin copiar el poema entero."],
  [("comentario", "texto en que se explica e interpreta una obra"), ("transmitir", "comunicar una emoción o idea a otros"), ("sugerir", "dar a entender algo sin decirlo directamente"), ("cierre", "última parte de un texto")],
  [("Completar un comentario", f"Poema: «{PERS}» Completa: «El poema transmite ___. El verso ‘el viento bostezó’ es una ___ porque ___.»",
    ["Busco el estado de ánimo: calma, noche tranquila.", "El viento hace algo humano: bostezar.", "Completo: «transmite calma», «personificación», «el viento hace algo humano»."],
    "Calma; personificación; el viento hace algo humano"),
   ("Mejorar una oración", "«El poema me gustó mucho.» ¿Cómo la mejoras?",
    ["Pregunto qué transmite el poema.", "Agrego un verso como evidencia.", "Escribo: «El poema transmite calma, porque en ‘el viento bostezó’ el viento actúa como alguien tranquilo»."],
    "Se agrega estado de ánimo, verso y razón")],
  [("Copiar todo el poema como comentario.", "Se cree que citar es comentar.", "Cita solo los versos necesarios y explícalos."),
   ("Mencionar una figura sin explicar su significado.", "Se queda en la clasificación.", "Di qué significa dentro del poema.")],
  ([E("¿Cuántas partes tiene el comentario de un poema que se explica en esta clase?", "3", "Inicio, explicación y cierre."),
    E("¿Qué debe citar un comentario: versos como evidencia o solo la opinión?", "Versos como evidencia", "Respaldan lo que se afirma."),
    E("¿«Me gustó» es un comentario completo o falta explicación?", "Falta explicación", "No dice qué transmite ni por qué.")],
   [E(f"Poema: «{COMP}» ¿Cuál es una buena oración inicial: «El poema habla del cariño por alguien» o «El poema tiene versos»?", "«El poema habla del cariño por alguien»", "Nombra el tema y lo que transmite."),
    E("¿Qué verbo es adecuado para comentar: «transmite» o «ladra»?", "Transmite", "Se usa para hablar de lo que comunica un texto."),
    E(f"Lee: «{HIPER}» ¿Qué figura se cita para explicar «Te esperé mil años en la esquina»: hipérbole o comparación?", "Hipérbole", "Exagera la espera.")],
   [E(f"Poema: «{FIN}» ¿Qué verso es una onomatopeya para citar en un comentario?", "«Pum, pum, tamborilea el techo»", "Imita el sonido de la lluvia."),
    arith("Un comentario tiene 1 oración de inicio, 3 de explicación y 1 de cierre. ¿Cuántas oraciones tiene?", "1+3+1", "Se suman las tres partes."),
    E(f"Poema: «{FIN}» ¿cuántos versos tiene?", versos(FIN), "Se cuentan separados por barras.")],
   [E("Un comentario dice «Hay una comparación» y nada más. ¿Qué le falta: citar el verso y explicar qué significa o más comparaciones?", "Citar el verso y explicar qué significa", "Un comentario necesita evidencia y explicación."),
    E("Un compañero copia el poema completo como comentario. ¿Está bien?", "No", "Copiar no es explicar.")],
   [E(f"Poema: «{FIN}» ¿Qué comentario es mejor: «Transmite calma, pues ‘quieto como un gato’ compara al hablante con un gato tranquilo» o «Es un poema con lluvia»?", "«Transmite calma, pues ‘quieto como un gato’ compara al hablante con un gato tranquilo»", "Incluye estado de ánimo, verso y figura."),
    E("Si tu comentario tiene tema, tres versos citados y una explicación para cada uno, ¿tiene evidencia suficiente?", "Sí", "Cada afirmación está respaldada.")]),
  [E("Debes entregar un comentario para el diario mural del curso. ¿Qué incluyes: estado de ánimo, versos como evidencia y una explicación de las figuras, o solo el título del poema?", "Estado de ánimo, versos como evidencia y una explicación de las figuras", "Son las partes de un comentario.")],
  [E("¿Un comentario incluye una opinión o solo copia el poema?", "Una opinión", "Explica e interpreta."),
   E("¿La evidencia son versos del poema o datos del autor?", "Versos del poema", "Respaldan la interpretación."),
   E("¿Un buen cierre expresa tu impresión?", "Sí", "Cierra con una opinión.")],
  ("Escribe un comentario de cuatro oraciones sobre este poema: «Bajo el puente duerme el agua, / la luna se desliza como un patinador, / y las luciérnagas bailan / en el pelo de la noche.» Debes: nombrar el estado de ánimo, citar una comparación y una personificación, y cerrar con tu impresión.",
   "El poema transmite calma y fantasía. En «la luna se desliza como un patinador» hay una comparación que muestra un movimiento suave. «Bajo el puente duerme el agua» es una personificación porque el agua hace algo humano: dormir; significa que el agua está quieta. Al leerlo, me imaginé una noche mágica junto al agua.",
   ["nombra el estado de ánimo", "cita versos con la figura correcta", "explica su significado", "cierra con una impresión"], ["comentario de cuatro oraciones"], ["copiar el poema", "figura sin explicar"], "Pide a alguien que subraye tu evidencia y compruebe que la explicación corresponde."),
  "Escribe un comentario de un poema que hayas leído, usando el modelo de tres partes.",
  "Compara tu comentario con el de un compañero y anota qué evidencias usaron.")

L(OA5, 6,
  MAT,
  "Aprenderé a revisar mi comentario de un poema para que sea claro y convincente para quien lo lea, y a corregir errores de contenido y de forma.",
  ["Escribo comentarios con evidencia.", "Uso figuras en mis explicaciones."],
  ["Revisar un comentario de poema es comprobar que cumple con lo que prometió. Pregúntate: ¿nombré el estado de ánimo?, ¿cité versos?, ¿expliqué lo que significa cada figura?, ¿se entiende para alguien que no leyó el poema? y ¿hay errores de ortografía o puntuación?",
   "La audiencia cambia el modo de explicar. Para niños pequeños, usa ejemplos simples y frases cortas; para un compañero, puedes dar razones más desarrolladas. También conviene citar el verso entre comillas para que el lector sepa de dónde sacaste la evidencia.",
   "Algunos errores frecuentes son: confundir figuras (decir comparación a una hipérbole), citar un verso que no existe, dar una explicación literal de una figura o escribir frases tan largas que se pierde el sentido. Corregir estos errores mejora el comentario."],
  [("revisar", "volver a leer para mejorar un texto"), ("audiencia", "personas a quienes se dirige un texto"), ("cita", "fragmento exacto de un texto, entre comillas"), ("claridad", "cualidad de lo que se entiende con facilidad")],
  [("Corregir una figura", f"Poema: «{HIPER}» Comentario: «‘Lloré un océano de tristeza’ es una comparación.» ¿Cómo lo corriges?",
    ["Miro el verso: no tiene «como» ni «cual».", "Exagera la tristeza.", "Corrijo: «Es una hipérbole porque exagera cuánto lloró»."],
    "Es una hipérbole porque exagera cuánto lloró"),
   ("Adaptar a la audiencia", "Debes explicar «el viento bostezó» a un niño de segundo básico. ¿Cómo lo dices?",
    ["Uso palabras simples.", "Digo qué hace el viento y qué significa.", "Escribo: «Es como si el viento tuviera sueño: sopla muy despacito»."],
    "Es como si el viento tuviera sueño y soplara despacito")],
  [("Corregir solo la ortografía.", "Se olvida el contenido.", "Revisa también figuras, evidencias y claridad."),
   ("Citar de memoria sin verificar.", "Se inventa el verso.", "Copia el verso exacto del poema.")],
  ([E("Al revisar un comentario, ¿debes comprobar que los versos citados existen en el poema?", "Sí", "Una cita falsa quita credibilidad."),
    E("Un comentario dice «El poema es muy lindo». ¿Qué falta: explicación con evidencia o más adjetivos?", "Explicación con evidencia", "No dice qué transmite ni por qué."),
    E("Los versos citados van entre comillas. ¿Verdadero o falso?", "Verdadero", "Las comillas indican una cita.")],
   [E(f"Poema: «{COMP}» Un comentario dice que «tu risa es como una campana» es una hipérbole. ¿Qué figura es en realidad?", "Una comparación", "Usa «como» para unir dos cosas."),
    E("Para explicarle una figura a un niño de 7 años, ¿conviene una frase corta con ejemplo o un párrafo con términos técnicos?", "Una frase corta con ejemplo", "Se adapta a la edad."),
    E("¿Qué revisas con la pregunta «¿se entiende para alguien que no leyó el poema?»: la claridad o el color del lápiz?", "La claridad", "Es una pregunta de audiencia.")],
   [arith("Un comentario tiene 80 palabras y quitas 12 repetidas y 8 que no aportan. ¿Cuántas palabras quedan?", "80-12-8", "Se restan las eliminadas."),
    E(f"Poema: «{PERS}» Comentario: «El verso ‘la luna le dio la mano’ muestra que la luna puede dar la mano de verdad». ¿Está bien interpretado el verso?", "No", "Es una personificación que no debe leerse literalmente."),
    E("Si una oración tiene 40 palabras y se pierde el sentido, ¿conviene dividirla o alargarla?", "Dividirla", "Las frases más cortas son más claras.")],
   [E("Un compañero lee tu comentario y dice que no sabe de qué poema hablas. ¿Qué agregas: el título o el tema del poema o más adjetivos?", "El título o el tema del poema", "El lector necesita saber de qué poema se trata."),
    E("Dos comentarios citan el mismo verso. Uno lo explica y el otro no. ¿Cuál es más completo?", "El que lo explica", "Una cita necesita explicación.")],
   [E(f"Poema: «{SON}» Revisa: «‘Plic, plic, plic’ es una personificación». ¿Cómo lo corriges?", "Es una onomatopeya que imita las gotas", "Imita un sonido."),
    arith("Tu lista de revisión tiene 5 puntos y tu comentario cumple 4. ¿Cuántos puntos te faltan?", "5-4", "Se resta lo cumplido del total.")]),
  [E("Lees tu comentario en voz alta a la clase y notas que una frase es muy larga y enredada. ¿Qué haces: la divides o la dejas?", "La divido", "Así se entiende mejor.")],
  [E("¿Debes revisar solo la ortografía?", "No", "También el contenido y la claridad."),
   E("¿Pensar en quién leerá ayuda a explicar mejor?", "Sí", "Permite adaptar el lenguaje."),
   E("¿Una cita falsa mejora el comentario?", "No", "La evidencia debe ser real.")],
  ("Revisa este comentario sobre el poema «Salta el sol sobre los techos, / la calle huele a manzana, / y yo, con las manos al viento, / quiero abrazar la mañana»: «El poema es lindo. ‘La calle huele a manzana’ es una comparación. Es de sol.» Corrige tres problemas y escribe una versión de tres oraciones.",
   "Problemas: no nombra el estado de ánimo, confunde la figura (el verso no tiene comparación; apela al olfato), no explica. Versión: «El poema transmite alegría. ‘La calle huele a manzana’ apela al olfato y crea la imagen de una mañana fresca. ‘Salta el sol’ es una personificación porque el sol hace algo humano.»",
   ["detecta los problemas", "corrige la figura", "explica el significado"], ["versión final de tres oraciones"], ["mantener el error de figura", "no explicar"], "Compara tu versión con el poema para comprobar que los versos están bien copiados."),
  "Pide a alguien que lea tu comentario y diga qué parte no entiende.",
  "Escribe dos versiones de una explicación de una figura: una para un niño pequeño y otra para tu curso.")

L(OA5, 7,
  MAT,
  "Aprenderé a transferir lo aprendido a un poema nuevo: analizar sentidos, estados de ánimo, figuras y efectos sonoros en un mismo texto.",
  ["Reconozco sentidos, figuras y efectos sonoros.", "Sé comentar un poema."],
  ["Transferir es usar en un texto nuevo todo lo aprendido. Ante un poema desconocido, sigue un recorrido: lee completo; identifica el estado de ánimo; busca palabras que apelen a los sentidos; reconoce personificaciones, comparaciones e hipérboles; escucha los efectos sonoros; y explica cómo todo eso refuerza lo que dice el poema.",
   "En un mismo poema pueden aparecer varias de estas herramientas. Por ejemplo, un poema sobre la lluvia puede usar una onomatopeya para imitar las gotas, una personificación para que la lluvia «toque la puerta» y una hipérbole para decir que cayó «un mar entero». Cada recurso aporta algo distinto: sonido, movimiento humano, exageración de la cantidad.",
   "Lo importante es explicar el efecto, no solo nombrar la figura. Por ejemplo: «La onomatopeya hace sentir la lluvia golpeando el techo». Si puedes decir qué logra cada recurso, entiendes mejor el poema y puedes disfrutarlo más."],
  [("transferir", "aplicar lo aprendido a un texto nuevo"), ("recurso", "herramienta del lenguaje que usa un autor"), ("efecto", "resultado que produce un recurso en el lector"), ("recorrido", "serie de pasos para analizar")],
  [("Analizar varios recursos", f"Lee: «{FIN}» Identifica una personificación y una onomatopeya.",
    ["«La lluvia toca la puerta»: la lluvia hace algo humano.", "«Pum, pum» imita el sonido de la lluvia en el techo.", "Son personificación y onomatopeya."],
    "Personificación: «La lluvia toca la puerta»; onomatopeya: «Pum, pum»"),
   ("Explicar un efecto", f"En el mismo poema, ¿qué efecto produce «llovió un mar entero en mi patio»?",
    ["Es una hipérbole.", "Nadie recibe un mar entero en un patio.", "Destaca que llovió muchísimo."],
    "Destaca que llovió muchísimo")],
  [("Nombrar la figura sin decir su efecto.", "Se queda en la clasificación.", "Agrega «lo que logra es…»."),
   ("Dejar fuera los efectos sonoros al analizar.", "Se olvida leer en voz alta.", "Lee el poema en voz alta para oír los sonidos.")],
  ([E(f"Lee: «{FIN}» ¿Cuántos versos tiene?", versos(FIN), "Se cuentan los versos separados por barras."),
    E("En el poema de la lluvia, ¿«Pum, pum» es una onomatopeya o una comparación?", "Una onomatopeya", "Imita un sonido."),
    E("«Quieto como un gato»: ¿qué figura es?", "Una comparación", "Usa «como» para unir dos cosas.")],
   [E(f"En «{FIN}», ¿qué figura es «La lluvia toca la puerta»?", "Una personificación", "La lluvia hace una acción humana."),
    E("¿Qué estado de ánimo transmite el poema de la lluvia: calma o enojo?", "Calma", "El hablante escucha tranquilo junto a la ventana."),
    E(f"En «{FIN}», ¿a qué sentido apela «Pum, pum, tamborilea el techo»?", "Al oído", "Es un sonido.")],
   [E(f"En «{FIN}» ¿cuántas figuras distintas se nombran en esta clase (personificación, comparación, hipérbole y onomatopeya)?", "4", "Aparece una de cada una."),
    arith("Un poema tiene 6 versos y una figura cada 2 versos. ¿Cuántas figuras tiene?", "6//2", "Se divide entre los versos por figura."),
    E(f"En «{FIN}», ¿qué verso es la hipérbole: el cuarto o el quinto?", "El cuarto", "«Llovió un mar entero en mi patio» exagera.")],
   [E("Un lector dice que «un mar entero» significa que de verdad cayó un mar. ¿Interpreta bien?", "No", "Es una exageración para destacar la lluvia."),
    E("¿Qué efecto produce la onomatopeya «Pum, pum» al leerla en voz alta: hace oír la lluvia o hace ver los colores?", "Hace oír la lluvia", "Imita un sonido.")],
   [E("Para analizar un poema nuevo, ¿qué haces primero: leer completo o buscar figuras en un verso?", "Leer completo", "Es el primer paso del recorrido."),
    E("Dos lectoras describen el efecto de «quieto como un gato». Ana: «sugiere calma y tranquilidad». Beto: «sugiere un animal que ataca». ¿Quién interpreta mejor?", "Ana", "Se ajusta al ambiente de calma del poema.")]),
  [E("Te entregan un poema nuevo y te piden analizarlo. ¿Qué haces primero: leerlo completo y en voz alta o escribir el comentario sin leer?", "Leerlo completo y en voz alta", "Es el primer paso del recorrido.")],
  [E("¿Qué es transferir?", "Aplicar lo aprendido a un texto nuevo", "Se usa en otro contexto."),
   E("¿Es importante explicar el efecto de una figura?", "Sí", "No basta con nombrarla."),
   E("¿Un poema puede tener varias figuras a la vez?", "Sí", "Pueden combinarse varias figuras.")],
  ("Analiza este poema nuevo: «Silba el viento entre las ramas, / bzz, bzz, bzz, vuela el abejorro; / la tarde es como un pan tibio / y el sol me guiña un ojo. / Tengo un millón de risas en el pecho, / y yo, feliz, canto con las flores.» Escribe: 1) estado de ánimo; 2) una onomatopeya; 3) una comparación; 4) una personificación; 5) una hipérbole, cada una con su efecto.",
   "1) Alegría. 2) «bzz, bzz, bzz» imita el zumbido del abejorro. 3) «la tarde es como un pan tibio» muestra una tarde cálida y agradable. 4) «el sol me guiña un ojo» hace al sol un cómplice amable. 5) «Tengo un millón de risas en el pecho» exagera la alegría que siente.",
   ["identifica cada recurso", "explica el efecto", "usa el poema como evidencia"], ["cinco respuestas con explicación"], ["nombrar sin explicar", "confundir figuras"], "Subraya cada recurso con un color distinto."),
  "Lee en voz alta un poema nuevo y marca tres recursos distintos.",
  "Escribe un poema de seis versos con una onomatopeya, una comparación y una hipérbole.")
